package org.sleepwell.app;
import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.ref.WeakReference;import java.nio.charset.CharacterCodingException;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.JSONException;
/** Retained explicit read/review/merge. Cancellation wins only before the atomic commit boundary. */
final class DiaryImportJob {
 enum Phase{EMPTY,CHOOSING,READING,REVIEW,MERGING,DONE,ERROR}
 static final class State{final Phase phase;final DiaryImport.Review review;final String message;State(Phase phase,DiaryImport.Review review,String message){this.phase=phase;this.review=review;this.message=message;}boolean busy(){return phase==Phase.CHOOSING||phase==Phase.READING||phase==Phase.MERGING;}}
 interface Observer{void changed(State state);}private static final Semaphore READ=new Semaphore(1);private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"diary-import-close"),new ThreadPoolExecutor.DiscardPolicy());
 final Context app;final DiaryStore.Factory factory;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private WeakReference<Observer> observer=new WeakReference<>(null);private final AtomicInteger gate=new AtomicInteger();private final AtomicReference<CancellationSignal> signal=new AtomicReference<>();private final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private volatile boolean closed;private volatile State state;int request=20000+java.util.concurrent.ThreadLocalRandom.current().nextInt(10000);
 DiaryImportJob(Context context,boolean interrupted){app=context.getApplicationContext();factory=DiaryStore.factory;state=new State(Phase.EMPTY,null,interrupted?"The earlier import screen was interrupted. No import resumes automatically. Choose and review the document again.":"");}
 State state(){return state;}void observe(Observer value){observer=new WeakReference<>(value);value.changed(state);}void detach(Observer value){if(observer.get()==value)observer.clear();}private void publish(State value){if(closed)return;state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
 boolean choose(){if(closed||state.busy())return false;request=request>=60000?20000:request+1;publish(new State(Phase.CHOOSING,state.review,"Choose your separate private diary JSON."));return true;}
 void cancelChoice(){if(state.phase==Phase.CHOOSING)publish(new State(state.review==null?Phase.EMPTY:Phase.REVIEW,state.review,"Document choice cancelled. No merge occurred."));}
 private boolean active(){return !closed&&gate.get()==0;}
 void read(Uri uri){if(closed||state.phase!=Phase.CHOOSING)return;if(uri==null||!"content".equals(uri.getScheme())){publish(new State(Phase.ERROR,null,"Choose a diary document through Android Files."));return;}gate.set(0);publish(new State(Phase.READING,null,"Reading and validating up to 4 MiB…"));worker.execute(()->{boolean admitted=false;try{if(!READ.tryAcquire())throw new IllegalStateException("Another diary document is still closing. Try again shortly.");admitted=true;byte[] bytes;CancellationSignal cancel=new CancellationSignal();signal.set(cancel);try{check();ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(uri,"r",cancel);if(file==null)throw new IOException("Diary document unavailable.");descriptor.set(file);try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(file);ByteArrayOutputStream output=new ByteArrayOutputStream()){check();byte[] block=new byte[8192];for(int n;(n=input.read(block))!=-1;){check();if(output.size()+n>DiaryImport.MAX_BYTES)throw new IllegalArgumentException("Choose a diary JSON up to 4 MiB.");output.write(block,0,n);}check();bytes=output.toByteArray();}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancel,null);}DiaryImport.Review review;try(DiaryStore store=factory.open(app)){review=DiaryImport.prepare(store,bytes,this::active);}check();main.post(()->{if(active())publish(new State(Phase.REVIEW,review,"Review entries and conflicts before merging. Existing diary data stays unchanged until Merge."));else publish(new State(Phase.ERROR,null,"Import cancelled before commit. No entries were merged."));});}catch(Exception failure){String error=notice(failure,false);main.post(()->publish(new State(Phase.ERROR,null,error)));}finally{if(admitted)READ.release();}});}
 void merge(Set<String> importAsNew){if(closed||state.phase!=Phase.REVIEW||state.review==null)return;DiaryImport.Review review=state.review;Set<String> choices=Set.copyOf(importAsNew);gate.set(0);publish(new State(Phase.MERGING,review,"Merging reviewed entries…"));worker.execute(()->{try(DiaryStore store=factory.open(app)){int added=DiaryImport.merge(store,review,choices,this::active,new DiaryImport.Commit(){public void begin(){if(!gate.compareAndSet(0,2))throw new CancellationException("Diary import cancelled before commit.");}public void committed(){gate.set(3);}});int kept=review.conflicts.size()-choices.size();main.post(()->publish(new State(Phase.DONE,null,"Merged "+added+" entries. Skipped "+review.identical+" identical entries and kept "+kept+" current conflicts. No existing entries were overwritten or deleted; imported entries have no challenge owner.")));}catch(Exception failure){boolean uncertain=gate.get()>=2;String error=notice(failure,uncertain);main.post(()->publish(new State(Phase.ERROR,null,error)));}});}
 private void check(){if(!active())throw new CancellationException("Diary import cancelled before commit.");}
 private static String notice(Exception failure,boolean uncertain){if(uncertain)return "The merge result could not be confirmed. Reopen the diary before trying again. Existing entries were not overwritten.";if(failure instanceof CancellationException)return "Import cancelled before commit. No entries were merged.";if(failure instanceof CharacterCodingException)return "The document is not valid UTF-8.";if(failure instanceof JSONException)return "Choose a valid diary_format 1 document with only the supported diary fields.";if(failure instanceof IllegalArgumentException||failure instanceof IllegalStateException){String text=failure.getMessage();if(text!=null&&!text.isBlank()&&text.length()<240)return text;}return "The diary import could not finish. No merge was committed; the original diary is kept.";}
 boolean cancel(){if(state.phase!=Phase.READING&&state.phase!=Phase.MERGING)return true;if(!gate.compareAndSet(0,1))return gate.get()==1;CancellationSignal cancel=signal.get();ParcelFileDescriptor file=descriptor.get();CANCEL.execute(()->{if(cancel!=null)cancel.cancel();if(file!=null)try{file.close();}catch(IOException ignored){}});return true;}
 void close(){if(closed)return;cancel();closed=true;observer.clear();worker.shutdown();}
}
